input.new_string:
/**
 * Next per-project issue number. Archived issues keep their number, and a
 * purged issue's number is never reused, so the max is the greater of every
 * remaining row and the project's high-water mark.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const reserved = getDb()
    .select({ value: issueNumberHighWater.highWater })
    .from(issueNumberHighWater)
    .where(
      and(
        eq(issueNumberHighWater.orgId, orgId),
        eq(issueNumberHighWater.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, reserved?.value ?? 0) + 1;
}

/** Records that `issueNumber` has been used so a later purge cannot free it. */
export async function rememberIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<void> {
  getDb()
    .insert(issueNumberHighWater)
    .values({ orgId, projectId, highWater: issueNumber })
    .onConflictDoUpdate({
      target: [issueNumberHighWater.orgId, issueNumberHighWater.projectId],
      set: {
        highWater: sql`max(${issueNumberHighWater.highWater}, ${issueNumber})`,
      },
    })
    .run();
}

