/**
 * Permanent removal of one issue and the rows that exist only for it.
 * The caller still has to drop search documents and return storage quota.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<{
  commentIds: readonly string[];
  attachmentBytes: readonly number[];
}> {
  const db = getDb();
  const current = db
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  await rememberIssueNumber(
    orgId,
    current.projectId as ProjectId,
    current.number,
  );

  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.issueId, issueId),
      ),
    )
    .run();

  const commentRows = db
    .delete(comments)
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
    )
    .returning({ id: comments.id })
    .all();

  const attachmentRows = db
    .delete(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, orgId),
        eq(attachments.issueId, issueId),
      ),
    )
    .returning({ sizeBytes: attachments.sizeBytes })
    .all();

  db.delete(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .run();

  return {
    commentIds: commentRows.map((row) => row.id),
    attachmentBytes: attachmentRows.map((row) => row.sizeBytes),
  };
}

