 * project, along with its label links, comments and attachments. Search
 * documents for the issue and its comments go with them, and the storage
 * counter gives back the megabytes those attachments were counted for.
 * Issue numbers are not reused. The audit rows past the window are still
 * purged outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      let cursor: string | null = null;
      for (;;) {
        const archived = await issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        });

        for (const issue of archived.items) {
          if (!isArchived(issue)) continue;
          if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

          const purged = await issueRepo.purgeIssue(orgId, issue.id);
          await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
          for (const commentId of purged.commentIds) {
            await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
          }

          const freedMb = purged.attachmentBytes.reduce(
            (sum, sizeBytes) => sum + Math.ceil(sizeBytes / (1024 * 1024)),
            0,
          );
          if (freedMb !== 0) {
            await usageRepo.incrementUsage(orgId, { storageMbUsed: -freedMb });
          }

          result.processed += 1;
        }

        if (archived.nextCursor === null) break;
        cursor = archived.nextCursor;
      }

